import{I as e,J as t,M as n,_ as r,g as i,h as a,p as o,t as s,u as c}from"./plugin-vue_export-helper-Dy_UwxR5.js";var l=JSON.parse(`{"path":"/forge/box/1.%E9%AD%94%E6%94%B9%E5%85%A8%E6%81%AF%E7%90%83.html","title":"魔改全息球 | 原版文档","lang":"zh-CN","frontmatter":{"title":"魔改全息球","createTime":"2026/3/29","icon":"/icon/fram.svg"},"git":{},"filePathRelative":"forge/box/1.魔改全息球.md","headers":[]}`),u={name:`1.魔改全息球.md`};function d(s,l,u,d,f,p){let m=e(`VPTable`);return n(),o(`div`,null,[l[1]||=a(`<p class="read-more">全息球作为tetra的材料大全，同时也是<strong>锻造模拟器</strong>，可根据不同材料的不同数据进行排列，方便玩家进行各种材料的排行，从而择优锻造。</p><h2 id="全息球gui" tabindex="-1"><a class="header-anchor" href="#全息球gui"><span>全息球GUI</span></a></h2><p>在原版tetra中，你需要手持全息球右键来打开GUI，来查看材料的属性或进行部件的模拟锻造。而本包进行了魔改，无需携带全息球，随时随地都可以按<kbd>H</kbd>(默认按键)来打开全息球的GUI。</p><p>当前版本已经对全息球GUI进行了汉化，在GUI的上方共有<code>[模块]</code>、<code>[结构]</code>、<code>[系统]</code>、<code>[额外模块]</code>、以及新添加的<code>[卷轴图鉴]</code>这五个部分。其中<code>[结构]</code>与<code>[系统]</code>两个部分暂无内容，因此仅介绍剩余三个部分。</p><h3 id="模块" tabindex="-1"><a class="header-anchor" href="#模块"><span>[模块]</span></a></h3><p>该部分共有<strong>弓</strong>、<strong>工具腰带</strong>、<strong>单头工具</strong>、<strong>刀剑</strong>、<strong>双头工具</strong>、<strong>双头工具</strong>、<strong>弩</strong>、<strong>盾牌</strong>以及<strong>材料</strong>9个板块。</p><h3 id="额外模块" tabindex="-1"><a class="header-anchor" href="#额外模块"><span>[额外模块]</span></a></h3><p>该部分分为三页，每一页都有<mark>材料</mark>板块，且功能与[模块]部分的“材料”板块完全相同，因此不再重复提及。</p>`,8),r(m,{"full-width":``},{default:t(()=>[...l[0]||=[c(`table`,null,[c(`thead`,null,[c(`tr`,null,[c(`th`,{style:{"text-align":`center`}},`第一页`),c(`th`,{style:{"text-align":`center`}},`第二页`),c(`th`,{style:{"text-align":`center`}},`第三页`)])]),c(`tbody`,null,[c(`tr`,null,[c(`td`,{style:{"text-align":`center`}},[i(`刀剑`),c(`br`),i(`鞋子`),c(`br`),i(`护腿`),c(`br`),i(`蒸汽引擎`),c(`br`),i(`头盔`),c(`br`),i(`胸甲`),c(`br`),i(`扳手`),c(`br`),i(`单头工具`),c(`br`),i(`锻造饰品`)]),c(`td`,{style:{"text-align":`center`}},[i(`荣耀之证`),c(`br`),i(`毒素瓶`),c(`br`),i(`手套`),c(`br`),i(`灾变之心`),c(`br`),i(`戒指`),c(`br`),i(`项链`),c(`br`),i(`原初温床`),c(`br`),i(`足力健`),c(`br`),i(`护心镜`)]),c(`td`,{style:{"text-align":`center`}},[i(`皇冠`),c(`br`),i(`锻造锤`)])])])],-1)]]),_:1}),l[2]||=a(`<h3 id="卷轴图鉴" tabindex="-1"><a class="header-anchor" href="#卷轴图鉴"><span>[卷轴图鉴]</span></a></h3><p>该部分共展示当前版本的七十四种卷轴，可通过<span style="color:green;">筛选器</span>对可用部位进行筛选。 <img src="/assets/image1-C3qE1jIk.webp" alt="筛选" loading="lazy"></p><h2 id="全息球模拟锻造" tabindex="-1"><a class="header-anchor" href="#全息球模拟锻造"><span>全息球模拟锻造</span></a></h2><h3 id="材料板块" tabindex="-1"><a class="header-anchor" href="#材料板块"><span>材料板块</span></a></h3><p>打开全息球GUI，点击<code>[模块]</code>或<code>[额外模块]</code>的<mark>材料板块</mark>，并点击任意材料，将会显示以下页面（以第一个材料为例）：</p><p><img src="/assets/image2-CBH8iq9Z.webp" alt="example" width="500" loading="lazy"></p><p>GUI上方将显示<code>排序</code>按钮与三级<code>过滤</code>按钮(过滤不分先后)。此外，<span style="color:gold;">橙色框</span>为<span style="color:goldenrod;">当前页面</span>，<span style="color:red;">红色框</span>为<span style="color:red;">上一级页面</span>，<span style="color:#d400ff;">紫色框</span>为<span style="color:#d400ff;">材料类型</span>。同时，当前页面被<span style="color:limegreen;">绿色横线</span>区分为上下两个区域，当鼠标在其中一个区域内滑动滚轮时，该区域页面将进行左右滑动。</p><p>当玩家需要对材料进行某个属性的排序时，可通过<code>排序</code>按钮选择属性，此时各材料将显示为该项属性的具体数值，并按照数值<mark>高低从左至右</mark>排列。同时，还可通过<code>过滤</code>按钮对材料进一步筛选。</p><hr><p>例如，玩家A想查看<strong>一阶段材料</strong>中<strong>硬度最高</strong>的一个，那么A需在<code>排序</code>中选择<mark>硬度</mark>，在任意<code>过滤</code>中选择<mark>一阶段材料</mark>即可，此时将鼠标移至任意材料，即可显示该材料信息：</p><p><img src="/assets/image3-DHY-yiA8.webp" alt="A" width="500" loading="lazy"></p><p>此时，GUI下方显示的材料信息出现了两种颜色，<span style="color:red;">红色表示：对于该属性，当前材料比之前选中的材料降低了数值</span>；<span style="color:limegreen;">绿色则表示该属性数值提高。</span></p><h3 id="其他板块" tabindex="-1"><a class="header-anchor" href="#其他板块"><span>其他板块</span></a></h3><p>以[模块]部分的<strong>刀剑</strong>板块为例：玩家A希望锻造一柄重型剑刃，于是打开全息球GUI并点击[模块]的<strong>刀剑</strong>板块，此时GUI显示<strong>附层</strong>、<strong>护手</strong>、<strong>剑柄圆头</strong>、<strong>剑刃</strong>、<strong>剑柄</strong>五个部件，同时左上角出现<mark class="tip">合成&gt;刀剑</mark>字样。</p><p>A点击<code>剑刃</code>部件，左上角显示为<mark class="tip">合成&gt;刀剑&gt;剑刃</mark>，以及两个<code>/</code>按钮，同时展示所有<mark>未隐藏的</mark>剑刃类型共8个。之后，A点击<code>重型剑刃</code>，GUI显示以下页面：</p><p><img src="/assets/image4-Dk0u9iRC.webp" alt="剑刃" width="300" loading="lazy"></p><p>其中红色框为<span style="color:red;">该部件的简要介绍</span>，黄色框为<span style="color:goldenrod;">该部件根据材料对应数值所能提供的属性</span>，绿色框为<span style="color:limegreen;">排序按钮</span>，蓝色框为<span style="color:blue;">材料名称搜索</span>，紫色框为<span style="color:#d400ff;">材料类型</span>。</p><p>此时玩家A移动鼠标悬浮至<span style="color:red;">红色框</span>内，显示如下：</p><blockquote><p>重型剑刃牺牲了攻击速度以增加伤害，总能在完全蓄力时发动横扫。</p></blockquote><p>接着又移动鼠标悬浮至<span style="color:goldenrod;">黄色框</span>内，显示如下：</p><p><img src="/assets/image5-Bu598oX2.webp" alt="悬浮" width="250" loading="lazy"></p><p>结合以上所展示的信息，A得知：<code>重型剑刃</code>是基于材料<mark class="important">硬度（主要）</mark>和 <mark>密度（次要）</mark> 来获得攻击伤害，同时基于硬度增加横扫之刃伤害，基于密度降低攻击速度。因此A认为应该选择<mark class="info">高硬度材料作为剑刃</mark>，于是便点击了绿色框进行排序,同时利用英文输入法状态下的<kbd>-</kbd>、<kbd>+</kbd>进行翻页，但并未找到<strong>硬度</strong>字样，只能选择<strong>伤害</strong>字样，此时各材料图标变成了数字，并按照数值高低从左至右排列 <mark class="tip">可按住<kbd>Shift</kbd>重新显示材料图标</mark> ，A利用鼠标滚轮，查看右边的材料，发现<strong>金属</strong>类型排列第一的材料数值最高，遂点击该材料，于是GUI下方显示该材料的信息：</p><p><img src="/assets/image6-BVEtW16s.webp" alt="选择" width="500" loading="lazy"></p><p>A将鼠标移到<span class="important">红圈内</span>，得知利用该材料制作<code>重型剑刃</code>部件需要使用<mark class="danger">9级锤子</mark>，接着A又将鼠标移到红圈<strong>左边</strong>的材料图标上，得知该材料为<strong>末影合金块</strong>，是<mark class="tip">阶段三</mark>的金属材料，此时A不小心按住了<kbd>Ctrl</kbd>键，发现了更多关于该材料的信息。</p><p>看完信息之后A又注意到，该材料会降低3.35的<strong>速度</strong>，因此A再次点击排列按钮，并选择了<code>攻击速度</code>，此时GUI显示材料数值按照增加攻击速度的多少从左至右排列，且GUI下方依旧留着<mark>重型末影合金剑刃</mark>的信息，接着A又将鼠标移至新排列第一的金属材料上：</p><p><img src="/assets/image7-BzJSG39c.webp" alt="排列" width="500" loading="lazy"></p><p>可以看到，这个叫做<mark class="important">经验块</mark>材料被与 <mark>末影合金块</mark> 进行了对比，且词条的绿色部分为<span style="color:green;">新增加的效果</span>，红色部分为<span style="color:red;">新减少的效果</span>，显而易见的，<strong>简直太差劲了！</strong>于是乎，A又将鼠标移至其他材料进行对比，最终决定还是先用“末影合金块”作为剑刃材料。但同时，A又注意到，“重型末影合金剑刃”各词条最下方的<mark class="important">3改进</mark>字样。因此A点击了该字样：</p><p><img src="/assets/image8-CSUTzcpq.webp" alt="点击" width="500" loading="lazy"></p><p>A将鼠标移至各个按钮，得知了这些<strong>改进</strong>的信息，当A将鼠标移动至红圈内时，发现上方的词条中<code>完整度</code>由<code>-6</code>变成了<code>-7</code>，但多出了一个数值为20%的 <mark>穿甲</mark> ，于是A按下红圈内的按钮，将鼠标移动至 <mark>穿甲</mark> 词条，发现该词条能提供<mark class="important">无视目标20%护甲值</mark>的效果。</p><p>当A查看完剩下的按钮之后，对剑刃材料的选择便有了想法，于是就想去查看其他部件，因此将鼠标移动至上方的<code>刀剑</code>并点击，回到了<code>刀剑</code>这一级的GUI，而此时<code>合成</code>的左边也出现一个<kbd>Q</kbd>的图标，显然，按<kbd>Q</kbd>也能返回上一级页面。</p><h2 id="配合锻造加工台" tabindex="-1"><a class="header-anchor" href="#配合锻造加工台"><span>配合锻造加工台</span></a></h2><p class="read-more">以瘟疫头盔为例</p><p><img src="/assets/image9-BhY8xV1W.webp" alt="头盔" width="500" loading="lazy"></p><p>由<span class="important">红色框</span>中的信息可知</p><ol><li>该部件由材料的<mark class="tip">硬度</mark>来提供<mark>防御</mark></li><li>由材料的<mark class="tip">韧性</mark>来增加<mark>毒属性伤害</mark></li></ol><p>而当你将任意材料置于<span style="color:blue;">蓝色框</span>内时</p><ul><li>上方将显示<span style="color:blue;">新旧材料提供的具体属性对比</span></li><li>将鼠标置于右边的<strong>查看可用材料</strong>按钮图标，可显示该部件能使用的材料类型，当你点击该按钮图标，将会跳转至全息球页面。</li></ul><p>此时，你可选中任意材料以查看该材料作为<strong>瘟疫头盔</strong>时所提供的各种属性，基本上是 <mark>防护[饰品/盔甲]</mark> 、 <mark>瘟疫[饰品/盔甲]</mark> 以及 <mark>完整度</mark> 。</p><p>通过点击<code>筛选</code>按钮，我们可以看到 <strong>[盔甲＆饰品]护甲值</strong> 等词条，但却并没有<strong>瘟疫[饰品/盔甲]</strong>词条。</p><div class="hint-container note"><p class="hint-container-title">注</p><p><strong>瘟疫伤害</strong>、<strong>火焰伤害</strong>词条均为<mark class="warning">主手生效</mark>，<mark class="danger">盔甲不生效</mark>。</p></div><p>所以，我们只能通过对<mark>比材料的韧性</mark>，来判断各个材料所提供的<strong>瘟疫[饰品/盔甲]</strong>词条数值高低。</p><p>基于此，你可以点击<code>[额外模块]</code>部分，再点击<code>材料</code>板块，点击筛选按钮，选择<code>韧性</code>，并选择你希望的过滤条件，比如<mark>1阶段材料</mark>，再按照<mark>瘟疫头盔</mark>的可用材料类型，来选择合适的材料。对比完材料的数值后，再点击[模块]部分，继续查看<mark>瘟疫头盔</mark>的内容。</p><p>经过初步了解，相信你已经对Tetra全息球有了全新的了解！然而，实践是检验真理的唯一标准，快到你的世界里尝试一番吧！</p>`,43)])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};